<?php require_once __DIR__.'/../../config/seguranca.php';exigirAdmin();$pageTitle='Editar opção';require __DIR__.'/../_header.php';$pdo=getPDO();$id=(int)($_GET['id']??0);$r=null;if($pdo){$st=$pdo->prepare('SELECT * FROM opcoes WHERE id=?');$st->execute([$id]);$r=$st->fetch();}?><div class="admin-heading"><div><h1>Editar opção</h1></div></div><?php if(!$r):?><div class="admin-card"><div class="empty-state">Opção não encontrada.</div></div><?php else:?><div class="admin-card"><form action="<?=url('admin/adicionais/atualizar.php')?>" method="post"><input type="hidden" name="csrf" value="<?=csrfToken()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><div class="form-grid"><div class="form-group"><label>Nome</label><input class="form-control" name="nome" required value="<?=e($r['nome'])?>"></div><div class="form-group"><label>Grupo</label><select class="form-control" name="tipo"><?php foreach(['fruta','creme','adicional','calda','acompanhamento'] as $t):?><option value="<?=$t?>" <?=$t===$r['tipo']?'selected':''?>><?=ucfirst($t)?></option><?php endforeach;?></select></div><div class="form-group"><label>Preço extra</label><input class="form-control" type="number" step="0.01" min="0" name="preco" value="<?=$r['preco_adicional']?>"></div><div class="form-group"><label>Ativo</label><label class="checkbox-row"><input type="checkbox" name="ativo" value="1" <?=$r['ativo']?'checked':''?>> Disponível</label></div></div><button class="admin-btn" style="margin-top:16px">ATUALIZAR</button></form></div><?php endif;?><?php require __DIR__.'/../_footer.php'; ?>
